ROOT <- Sys.getenv("LEGIONELLA_ROOT")
if (!nzchar(ROOT)) stop("Set LEGIONELLA_ROOT")
library(readr); library(dplyr); library(broom)
atlas <- read_tsv(file.path(ROOT,"08_evidence_atlas","host_dependency_evidence_atlas.tsv.gz"), show_col_types=FALSE)
truth <- function(x) as.integer(toupper(as.character(x)) %in% c("TRUE","1","YES"))
getcol <- function(n, default=0) if(n %in% names(atlas)) suppressWarnings(as.numeric(atlas[[n]])) else rep(default,nrow(atlas))
d <- atlas %>% mutate(outcome=as.integer(grepl("^F", as.character(functional_tier))), lcv=truth(lcv_spatial_supported), ppi=truth(ppi_AB_flag), response=truth(stable_cross_cohort), nstudy=getcol("expression_n_studies"), chronos=getcol("u937_chronos_gene_effect"), common=truth(common_essential_flag), degree=getcol("cross_pathogen_degree"), pmids=getcol("cross_pathogen_pmids")) %>% group_by(human_symbol) %>% summarise(across(c(outcome,lcv,ppi,response,nstudy,chronos,common,degree,pmids), ~median(.x,na.rm=TRUE)), .groups="drop")
d <- d %>% mutate(across(everything(), ~ifelse(is.finite(.x), .x, 0)))
fit <- glm(outcome ~ lcv + ppi + response + nstudy + chronos + common + degree + pmids, data=d, family=binomial())
out <- broom::tidy(fit, conf.int=TRUE, exponentiate=TRUE) %>% filter(term!="(Intercept)")
write_tsv(out, file.path(ROOT,"13_postfreeze_interpretation","joint_multivariable_evidence_model.tsv"))
writeLines(c("Joint multivariable model: fitness-filtered CRISPR evidence ~ simultaneous LCV, PPI, response and ascertainment covariates.", paste(capture.output(summary(fit)),collapse="\n")), file.path(ROOT,"13_postfreeze_interpretation","joint_multivariable_evidence_model_summary.txt"))
print(out)
